  "building.stadium.description": "族民奢侈品消耗 −{luxuryUpkeepReductionPerLevel}%/级（最多 −{maximumLuxuryUpkeepReduction}%）；装备政策卡「直播竞技」时，额外市政点产出 = 人口 × 体育场等级。",
  "building.stadium.name": "体育场",
  "building.temple.description": "信仰产出 +{faithOutputBonus}%/级（装备政策卡「神学」后翻倍）",
  "building.temple.name": "神庙",
  "building.tenement.description": "人口上限 +{populationCapacityPerLevel}/级；每级额外增加 {luxuryUpkeepIncreasePerLevel}% 居民奢侈品消耗",
  "building.tenement.name": "廉租社区",
  "building.terra_engine.description": "把泰拉推离原有轨道。建成 {requiredEngineCount} 座并灌满星核炉芯池，即完成流浪泰拉挑战。",
  "building.terra_engine.name": "行星发动机",
  "building.terra_launch.name": "泰拉发射场",
  "building.terra_vat.description": "每级增加 {populationCapacityPerLevel} 人口上限，并每秒消耗热液能 {hydroEnergyConsumptionPerSecond}；优先取自星核炉芯池，池空后占用热液能流。停用即断电：该座提供的人口上限立刻消失，超出上限的族民会陆续离开。",
  "building.terra_vat.name": "泰拉地壳密闭水舱巨构",
  "building.theater.description": "官员（书手）市政点产出 +{officialCivicOutputBonus}%/级",
  "building.theater.name": "歌剧院",
  "building.tidemachine.description": "把建设潮道的知识用于开发热液能，潮汐推动精妙的连杆飞速运转：每级产生热液能 {hydroEnergyPerLevelPerSecond}/秒，不产生污染。",
  "building.tidemachine.name": "潮汐往复机",
  "building.titan_cloud_harvester.name": "泰坦星气云采集站",
  "building.titancloud.description": "采集泰坦星气云：每级每秒产出热液能 {hydroEnergyOutputPerSecond}（不消耗暖石）、燃料 {fuelOutputPerSecond}。采集设施数量由建筑等级决定。",
  "building.upgrade.name.castle": "城堡",
  "building.void_altar.description": "以族民为祭：建造首级消耗人口 {firstLevelPopulationCost}，升至第二级消耗 {secondLevelPopulationCost}，升至第三级消耗 {thirdLevelPopulationCost}（按当前职业分配比例扣减）。完成全部 {altarLevelCount} 级后，虚境之门为你打开。",
  "building.void_altar.name": "虚境祭坛",
  "building.warmnest.description": "每级使族民的藻食消耗降低 {kelpUpkeepReduction}%",
  "building.warmnest.name": "深海鱼牧场",
