  "challenge.award.success_log": "{challengeName}挑战达成：{goalText}。永久奖励已生效。",
  "challenge.begin.replay_log": "再次挑战：{challengeName} · {tierName}（重复挑战不发奖，成绩计入排行榜）。",
  "challenge.begin.start_log": "挑战开始：{challengeName} · {tierName}",
