  "challenge.notice.three_launch_sites.progress": "欧罗巴 {europaLevel}/11 · 泰拉 {terraLevel}/11 · 恩克拉多斯 {enceladusLevel}/11{completionWarning}",
  "challenge.pollution_stage.blighted_deep": "腐渊",
  "challenge.pollution_stage.clear_sea": "澄海",
