  "civic.data.ascend_to_the_verge.description": "本身没有产出。戴森球建设完成后，文明将迎来「飞升虚境」的结局——到那时，语言已不足以承载你们的名字。",
  "civic.data.ascend_to_the_verge.inspiration": "前置：虚境探索。鼓舞：虚境祭坛达到 {buildingLevel} 级。",
