  "civic.data.city_supply.inspiration": "鼓舞：廉租社区达到 {buildingLevel} 级。",
  "civic.data.city_supply.name": "城市供给",
  "civic.data.civilizational_design.description": "本轮回破壳时获得的轮回点 +{prestigePointBonusPercent}%。",
  "civic.data.civilizational_design.inspiration": "鼓舞：轮回次数达 {prestigeCycleThreshold} 次。",
  "civic.data.civilizational_design.name": "文明构造",
  "civic.data.common_destiny.description": "解锁政策卡「血肉苦弱」（精铁/钢/θ金属产出 +{metalOutputBonusPercent}%）；政策卡「各员一层奋力努力」（工艺效率 +{craftingEfficiencyBonusPercent}%、幸福度 −{happinessPenalty}，取代工业化配给）。",
  "civic.data.common_destiny.inspiration": "前置：超远见主义。鼓舞：采用政体「星海共同体」。",
  "civic.data.common_destiny.name": "共同命运",
  "civic.data.coral_cultivation.description": "解锁政策卡「珊瑚培育」：珊瑚产出 +{coralOutputBonusPercent}%。",
  "civic.data.coral_cultivation.inspiration": "鼓舞：累计产出珊瑚达 {coralGatherThreshold}。",
  "civic.data.coral_cultivation.name": "珊瑚培育",
  "civic.data.cosmic_indifference.description": "解锁政策卡「我们在此」（取代「天赋神权」），以及奇观「Khalifa 宇宙望远镜」。",
  "civic.data.cosmic_indifference.inspiration": "鼓舞：空间站等级超过 {buildingLevelThreshold}。",
  "civic.data.cosmic_indifference.name": "宇宙冷漠",
  "civic.data.craftsmanship.description": "解锁政策卡「技艺」（工坊效率 +{workshopEfficiencyPercent}%）、「征夫发役」（纪元 {firstEra}–{lastEra} 奇观建造消耗 −{wonderCostReductionPercent}%）。",
  "civic.data.craftsmanship.inspiration": "鼓舞：建成 {buildingLevel} 级工坊。",
  "civic.data.craftsmanship.name": "技艺",
  "civic.data.cultural_heritage.description": "所有奇观额外 +{wonderCivicPointBonusPercent}% 市政点获取；解锁政策卡「旅游观光」。",
  "civic.data.cultural_heritage.inspiration": "鼓舞：建成 {wonderCountThreshold} 座奇观。",
  "civic.data.cultural_heritage.name": "文化遗产",
  "civic.data.distributed_sovereignty.description": "解锁政体「星际联邦」（{policySlotCount} 个政策卡槽，全产 +{globalProductionBonusPercent}%，幸福度 +{happinessBonus}）；国家后缀改为星际联邦。",
  "civic.data.distributed_sovereignty.inspiration": "前置：星际政治。鼓舞：异星/太空建筑（瑞亚/泰坦/卫星/空间站/机械湾/生物材料）合计等级超过 {totalBuildingLevels}。",
  "civic.data.distributed_sovereignty.name": "分布式主权",
  "civic.data.divine_grace_authority.description": "解锁政体「教权国」（{policySlotCount} 个政策卡槽，所有建筑每级 +{faithPerBuildingPerSecond} 信仰/秒）；采用时弹窗命名，城堡更名为「圣座居所」。",
  "civic.data.divine_grace_authority.inspiration": "鼓舞：完成市政「意识形态」。",
