  "game.story.unlock.civics.action": "进入市政页",
  "game.story.unlock.civics.line_1": "这是鲛人们第一次围坐在同一张石桌旁。",
  "game.story.unlock.civics.line_2": "集中食物、分配任务、解决分歧……文明从这里开始。",
  "game.story.unlock.civics.system_description": "现在可以研究市政、选择政体，并装配政策卡。",
