  "game.story.unlock.civics.title": "市政页解锁",
  "game.story.unlock.company.action": "进入公司页",
  "game.story.unlock.company.line_1": "我们吃生物合成的鱼卵，吃在实验室里生长的海藻，该死，连光合作用都被注册了！",
  "game.story.unlock.company.system_description": "系统自动成立藻食与珊瑚两家公司，随成立时间成长，提供对应资源产出加成。",
  "game.story.unlock.company.system_title": "公司系统已开放",
  "game.story.unlock.company.title": "公司页解锁",
  "game.story.unlock.faith.action": "进入信仰页",
  "game.story.unlock.faith.line_1": "祭司把潮汐、族民与深海火光刻在同一张薄石板上。",
  "game.story.unlock.faith.line_2": "但为何每一位祭司对此都有不同的理解呢？",
  "game.story.unlock.faith.system_description": "现在可以查看信仰产出、全局加成，并为你的宗教命名。",
  "game.story.unlock.faith.system_title": "信仰系统已开放",
  "game.story.unlock.faith.title": "信仰页解锁",
  "game.story.unlock.prestige.action": "了解",
  "game.story.unlock.prestige.line_1": "鲛人的诵经声伴随深海的浪潮传遍王国的角落，",
  "game.story.unlock.prestige.line_2": "祭司们说周期性的暖流与浪潮象征着文明的轮回……",
  "game.story.unlock.prestige.line_3": "从此，每一次终结这一局都将开启一段新的轮回——轮回点可在轮回商店换取永恒的增益。",
  "game.story.unlock.prestige.title": "轮回系统解锁",
  "game.story.unlock.star_map.action": "进入星图页",
  "game.story.unlock.star_map.line_1": "自鲛人首次抬头望向头顶的天壳，已经过去了不知多少岁月。",
  "game.story.unlock.star_map.line_2": "但在今天，他们首次望见了冰层后闪熠的群星。",
  "game.story.unlock.star_map.system_description": "现在可以查看欧罗巴、土星，以及本周目已经发射的卫星和空间站。",
  "game.story.unlock.star_map.system_title": "星图系统已开放",
  "game.story.unlock.star_map.title": "星图页解锁",
  "game.story.unlock.technology.action": "进入科技页",
  "game.story.unlock.technology.line_1": "鲛人将细小坚韧的深海藻类打了个结，「这代表今天，」他说。",
  "game.story.unlock.technology.line_2": "随后，他又打了第二个结，「这代表明天。」",
  "game.story.unlock.technology.title": "科技页解锁",
  "game.story.unlock.wonder.action": "进入奇观页",
  "game.story.unlock.wonder.line_1": "十余名石工师把蓝图摊在石台上，最终成品的线条一路越过了整座巢穴。",
  "game.story.unlock.wonder.system_description": "现在可以查看并建造独特奇观；建成后将永久留存并提供增益。",
  "game.story.unlock.wonder.system_title": "奇观蓝图已揭晓",
  "game.story.unlock.wonder.title": "奇观页解锁",
  "game.story.unlock.workshop.action": "进入工坊",
  "game.story.unlock.workshop.line_1": "砧、锤、绳索与熟稔运用的匠人。",
  "game.story.unlock.workshop.line_2": "如果一件工具能替我们重复昨天的动作，是不是也能用来做新的创造？",
  "game.story.unlock.workshop.system_description": "现在可以制造工艺品、购买职业工具，并安装永久升级。",
