  "tech.adiabatic.name": "绝热材料",
  "tech.adiabatic.unlock_desc": "欧罗巴冰面发射场可切换制造太阳帆（每级每秒耗铀{sailUraniumRate}、强工质火箭引擎{sailEngineRate}、θ金属自适应薄膜{sailFilmRate}、热液能{sailHydrothermalRate}）或戴森球节点（每级每秒耗铀{nodeUraniumRate}、强工质火箭引擎{nodeEngineRate}、θ金属自适应薄膜{nodeFilmRate}、钛合金板{titaniumPlateRate}、热液能{nodeHydrothermalRate}）。星图开启戴森球终局面板：太阳帆{solarSailGoal}+ 戴森球节点{dysonNodeGoal}即通关。",
  "tech.alien_eng.name": "大型异星工程",
  "tech.alien_eng.unlock_desc": "建筑：马尔斯工造中心（造价{biomaterialCost}θ生物金属 {engineCost}强工质火箭引擎，每级产钛与钛金板件）。",
  "tech.ancient.effect_desc": "所有太空建筑建造消耗 {effectPercent1}（多个减免源乘法叠加，合计至多 {maximumReduction}）。星屑跨周目累计，在周目结算时发放。",
