  "ui.faith.global_bonus.explanation": "按信仰存量的数量级提供全产出加成：{bonusExamples}。每增加一个数量级，加成提高{bonusPerMagnitude}。此加成影响{affectedResources}等全部资源，但不影响信仰本身（避免正反馈）。",
