  "ui.intro.achievements.description": "文明里程碑收藏墙。",
  "ui.intro.achievements.title": "这是什么 · 成就",
  "ui.intro.challenges.description": "给周目附加全局规则的自限玩法：禁保温、压人口、限岗位、限时间等，规则越难，通关后给的永久奖励越强。",
  "ui.intro.challenges.title": "这是什么 · 挑战",
  "ui.intro.civic.description": "按纪元推进的市政树，科技会解锁建筑、政体与政策卡。",
  "ui.intro.civic.step": "1. 政体有不同的被动与政策槽数量，越后期的政体槽数量越多。<br>其次， 政策卡必须填入政策槽中才能发挥作用。",
  "ui.intro.civic.title": "这是什么 · 市政",
  "ui.intro.company.description": "文明的经济实体层（ERA{eraNumber} 市政《宏观经济学》解锁）：系统自动成立藻食与珊瑚两家公司，随成立时间从乡镇成长为地方、全国企业，提供对应资源产出加成，同时恒增 {luxuryConsumptionIncreasePercent} 奢侈品消耗。",
  "ui.intro.company.title": "这是什么 · 公司",
  "ui.intro.faith.description": "信仰系统：研究《神学》后开放，信仰点驱动宗教加成。",
  "ui.intro.faith.step": "1. 每个轮回的信仰存量会积累为旧日信仰，在每个轮回都会发挥作用。<br>其次， 在解锁神学，建立宗教后，轮回可以获得轮回点。",
  "ui.intro.faith.title": "这是什么 · 信仰",
  "ui.intro.folk.description": "人口与职业层：族民吃藻食、住住房，可以被分配为采集者/采石工/学者等职业，驱动各类产出。",
  "ui.intro.folk.step": "人口顶到上限就建更多住房，藻食必须超过{kelpThreshold}才会有新增人口。",
  "ui.intro.folk.title": "这是什么 · 族民",
  "ui.intro.help.tooltip": "这是什么？",
  "ui.intro.meta.description": "跨周目成长层：破壳结算给轮回点，繁星结算给星屑在商店换永久增益。",
  "ui.intro.meta.step": "解锁神学后才能获得轮回点，破壳后才会获得星屑。",
  "ui.intro.meta.title": "这是什么 · 轮回商店",
  "ui.intro.star_dome.description": "跨周目局外资源层：星屑在轮回结算时按太空与异星设施、星空探索和戴森球进度发放，可购买永久强化，也能与轮回点按固定汇率互换。",
  "ui.intro.star_dome.step": "建成首座轨道卫星即可永久解锁本页；之后即使进入新周目、卫星等级归零，商店仍保持开放。星屑在合格轮回结算时入账。",
  "ui.intro.star_dome.title": "这是什么 · 星屑商店",
  "ui.intro.star_map.description": "破壳后解锁的星空探索视图，前期为母星所在行星系，后期会解锁恒星系界面。",
  "ui.intro.star_map.step": "这里的建筑和巢穴标签下星海区建筑是一致的。",
  "ui.intro.star_map.title": "这是什么 · 星图",
  "ui.intro.tech.description": "按纪元推进的科技树，科技会解锁建筑、资源线与后续系统；",
  "ui.intro.tech.step": "1. 每项科技内容起初是隐藏的，要达成尤里卡条件才会展示具体内容并可以研究。<br>其次， 研究完一个纪元的关键节点，就会展示下一个纪元科技的尤里卡，可以提前进行准备。",
  "ui.intro.tech.title": "这是什么 · 科技",
  "ui.intro.village.description": "鲛人国度所有已经解锁的建筑列表，你可以在这里对其进行升级。",
  "ui.intro.village.step": "使用手动「采藻食」、「采珊瑚」攒够资源，建起深海藻场，礁口巢。",
  "ui.intro.village.title": "这是什么 · 巢穴",
  "ui.intro.wonder.description": "大型工程项目：耗巨量资源建成，给全局强增益或解锁终局机制（如天穹钻机）。",
  "ui.intro.wonder.title": "这是什么 · 奇观",
  "ui.intro.workshop.description": "把原料加工成进阶物资，以及购买永久工艺升级。",
  "ui.intro.workshop.step": "工艺效率越高，消耗同样材料获得的进阶物资就越多。",
  "ui.intro.workshop.title": "这是什么 · 工坊",
